package service
import("context";"database/sql";"errors";"time";"go-repair-center/internal/repository";"go-repair-center/internal/repository/mysql")
type QuotationService struct{*ResourceService;repo *mysql.QuotationRepository;validDays int;threshold float64}
func NewQuotationService(repo *mysql.QuotationRepository,validDays int,threshold float64)*QuotationService{return &QuotationService{ResourceService:NewResourceService(repo,"quotation","repair_order_id"),repo:repo,validDays:validDays,threshold:threshold}}
func(s *QuotationService)CreateVersion(ctx context.Context,input repository.Record,items []repository.Record,userID int64,key string)(repository.Record,error){if key==""{return nil,errors.New("Idempotency-Key required")};total:=number(input["labor_fee"])+number(input["parts_fee"])+number(input["inspection_fee"])+number(input["other_fee"]);input["total_amount"]=total;input["valid_until"]=time.Now().AddDate(0,0,s.validDays);input["customer_status"]="PENDING";input["status"]="DRAFT";input["created_by"]=userID;if total>s.threshold{input["approval_status"]="PENDING"}else{input["approval_status"]="NOT_REQUIRED"};var out repository.Record;err:=s.repo.WithTransaction(ctx,func(tx *sql.Tx)error{record,e:=s.repo.CreateVersion(ctx,tx,input,items);out=record;return e});return out,err}
func(s *QuotationService)History(ctx context.Context,repairOrderID int64)([]repository.Record,error){return s.repo.VersionHistory(ctx,repairOrderID)}
func(s *QuotationService)Approve(ctx context.Context,id,userID int64,approved bool)(repository.Record,error){status:="REJECTED";if approved{status="APPROVED"};return s.Update(ctx,id,repository.Record{"approval_status":status,"approved_by":userID,"approved_at":time.Now()})}
func number(v any)float64{switch n:=v.(type){case float64:return n;case int:return float64(n);case int64:return float64(n);default:return 0}}